@wraps(view)
@csrf_exempt  # GET endpoints — CSRF is irrelevant for state-changing protection here
def wrapper(request, *args, **kwargs):
    token = _extract_token(request)
    key = APIKey.authenticate(token)
    if key is None or not key.is_active:
        return JsonResponse({"error": "unauthorized"}, status=401)
    owner = key.owner
    if owner is None or not owner.is_active or owner.is_disabled:
        return JsonResponse({"error": "unauthorized"}, status=401)
    request.api_user = owner
    request.user = owner
    return view(request, *args, **kwargs)

